#define HRTIM_AD_PIN_DEMO          1U
#define DEMO_SELF_CHECK_TIMEOUT_MS 200U

/* USER CODE END PD */

/* Private macro -------------------------------------------------------------*/
/* USER CODE BEGIN PM */

/* USER CODE END PM */

