static volatile uint32_t g_tick_1ms = 0U;
#else
static volatile uint32_t g_demo_hrtim_rep_count = 0U;
#endif
static volatile uint16_t g_user_adc_result[USER_POWER_ADC_CHANNEL_COUNT] = {0U};
/* USER CODE END PV */

/* Private function prototypes -----------------------------------------------*/
